            fixture.player.setPosition(8.5,65,8.5);
            fixture.world.put(new BlockPos(8,64,8),FloorBlocks.GRAVITY_FLOOR.getDefaultState());
            FloorWorldFields.onChunkLoad(new ChunkEvent.Load(fixture.world.world().getChunk(0,0)));
